#!/usr/bin/env bash
# lint-product-readiness-contract — keep Customer Signal OS proof gates wired
# into the product, build, smoke, and proposal surfaces.

set -euo pipefail

cd "$(dirname "$0")/.."

fail=0

require_file() {
  local file="$1"
  if [[ ! -f "$file" ]]; then
    echo "ERROR: missing file $file" >&2
    fail=1
  fi
}

require_contains() {
  local file="$1"
  local needle="$2"
  local label="$3"
  require_file "$file"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if ! grep -qF "$needle" "$file"; then
    echo "ERROR $file: missing $label ($needle)" >&2
    fail=1
  fi
}

require_regex() {
  local file="$1"
  local pattern="$2"
  local label="$3"
  require_file "$file"
  if [[ ! -f "$file" ]]; then
    return
  fi
  if ! grep -qE "$pattern" "$file"; then
    echo "ERROR $file: missing $label ($pattern)" >&2
    fail=1
  fi
}

